function show(el){el.classList.remove('hidden')}function hide(el){el.classList.add('hidden')}
function enterRoutes(){state='select';hide(ui.title);hide(ui.results);hide(ui.pause);hide(ui.countdown);show(ui.routes);game.classList.remove('playing');renderUnlocks();populateRuns()}
function populateRuns(){const select=$('runSelect');select.innerHTML='';RUNS[routeIndex].forEach((run,i)=>{const option=document.createElement('option');option.value=i;option.textContent=`${run.name} · ${run.difficulty} · ${run.length.toLocaleString()} M`;select.appendChild(option)});runIndex=0;select.value='0'}
function renderUnlocks(){document.querySelectorAll('.route-card').forEach((card,i)=>{const locked=best<ROUTES[i].unlock;card.classList.toggle('locked',locked);card.setAttribute('aria-disabled',String(locked));card.querySelector('b').textContent=locked?`BEST ${ROUTES[i].unlock.toLocaleString()}`:`${ROUTES[i].elevation.toLocaleString()} FT`});document.querySelectorAll('.swatches button').forEach((b,i)=>{const locked=best<[0,3500,7500][i];b.classList.toggle('locked',locked);b.title=locked?`Unlock at ${[0,3500,7500][i].toLocaleString()} best score`:''})}
