function finish(){if(state==='over')return;state='over';game.classList.remove('playing');const final=Math.floor(score),wasBest=final>best;best=Math.max(best,final);store.set('alpineRushBest',best);$('titleBest').textContent=String(best).padStart(6,'0');$('finalScore').textContent=final.toLocaleString();$('finalDistance').textContent=`${Math.floor(distance).toLocaleString()} M`;$('finalCombo').textContent=`${bestCombo}×`;$('finalClears').textContent=clears;$('finalTricks').textContent=trickCount;$('finalBestTrick').textContent=bestTrick;$('newBest').classList.toggle('hidden',!wasBest);const rank=final>8000?'S':final>5000?'A':final>2500?'B':'C';$('medal').textContent=rank;$('resultTitle').textContent={S:'LEGENDARY LINE.',A:'MOUNTAIN MASTERED.',B:'SOLID LINE.',C:'ONE MORE RUN.'}[rank];ui.runProgressFill.style.transform='scaleX(1)';ui.runProgressValue.textContent='100%';show(ui.results);renderUnlocks()}
