function beep(freq,duration,type='triangle',volume=.045){if(!sound)return;try{const ac=beep.ac||(beep.ac=new(window.AudioContext||window.webkitAudioContext)()),o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.setValueAtTime(freq,ac.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(40,freq*.72),ac.currentTime+duration);g.gain.setValueAtTime(volume,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+duration);o.connect(g).connect(ac.destination);o.start();o.stop(ac.currentTime+duration)}catch{}}
function jump(){if(state==='title'){enterRoutes();return}if(state==='select'){beginCountdown();return}if(state==='over'){beginCountdown();return}if(state==='playing'&&player.jump===0){Object.assign(player,{jumpV:580+speed*45,jump:.1,spin:0,spinV:0,flip:0,flipV:0,grabTime:0,trickActive:false,compression:.85});jumps++;burst(player.x*W,player.y*H+25,'#effcff',8);beep(480,.12)}}
function trickLabel(){const degrees=Math.round(Math.abs(player.spin)*180/Math.PI/90)*90,flipProgress=Math.abs(player.flip)/(Math.PI*2),flipName=player.flip<0?'FRONTFLIP':'BACKFLIP',parts=[];if(degrees)parts.push(`${degrees}° ${player.spin<0?'LEFT':'RIGHT'}`);if(flipProgress>.12)parts.push(flipProgress>1.5?`DOUBLE ${flipName}`:flipName);if(player.grabTime>.18)parts.push('SAFETY GRAB');return parts.join(' + ')||'SETTING UP'}
function landTrick(){const attempted=Math.abs(player.spin)>.35||Math.abs(player.flip)>.35||player.grabTime>.18;if(!attempted)return true;const tau=Math.PI*2,spinR=Math.round(player.spin/tau),flipR=Math.round(player.flip/tau),spinError=Math.abs(player.spin-spinR*tau),flipError=Math.abs(player.flip-flipR*tau);if(spinError>.75||flipError>.75){toast('FAILED LANDING','ROTATION INCOMPLETE');hitObstacle({hit:false},0);return false}const rotations=Math.abs(spinR)+Math.abs(flipR),flipLabel=flipR?(Math.abs(flipR)===1?(flipR<0?'FRONTFLIP':'BACKFLIP'):`${Math.abs(flipR)}× ${flipR<0?'FRONTFLIP':'BACKFLIP'}`):'',label=[spinR?`${Math.abs(spinR)*360}° ${spinR<0?'LEFT':'RIGHT'}`:'',flipLabel,player.grabTime>.18?'SAFETY GRAB':''].filter(Boolean).join(' + '),points=Math.max(150,rotations*450+(player.grabTime>.18?250:0))*combo;trickCount++;scorePop(points,player.x*W,player.y*H-45,label);if(points>bestTrickPoints){bestTrickPoints=points;bestTrick=label}combo=Math.min(8,combo+Math.max(1,rotations));comboTime=3.2;bestCombo=Math.max(bestCombo,combo);slowmo=.12;burst(player.x*W,player.y*H,'#ffd260',22);toast('TRICK LANDED',`${label} · +${points}`);beep(880,.18);return true}
function toast(label,value=''){ui.toast.querySelector('small').textContent=label;ui.toast.querySelector('strong').textContent=value;ui.toast.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>ui.toast.classList.remove('show'),850)}
function scorePop(points,x,y,label){score+=points;popups.push({x,y,text:`+${points}`,label,life:1});ui.scoreDelta.textContent=`+${points}`;ui.scoreDelta.classList.remove('pop');void ui.scoreDelta.offsetWidth;ui.scoreDelta.classList.add('pop')}
function burst(x,y,color,count=14){for(let i=0;i<count;i++)particles.push({x,y,vx:(Math.random()-.5)*170,vy:-20-Math.random()*130,life:.45+Math.random()*.5,size:2+Math.random()*5,color})}

