$('enterButton').onclick=enterRoutes;$('startButton').onclick=beginCountdown;$('restartButton').onclick=beginCountdown;$('resumeButton').onclick=togglePause;$('pauseButton').onclick=togglePause;$('selectButton').onclick=enterRoutes;$('quitButton').onclick=()=>{hide(ui.pause);enterRoutes()};
