const boostFill=$('boostFill'),boostValue=$('boostValue');
function updateBoostUI(){boostFill.style.transform=`scaleX(${boostEnergy/100})`;boostValue.textContent=`${Math.round(boostEnergy)}%`;boostFill.style.background=boostEnergy>=35?'linear-gradient(90deg,#62d9f5,#ffd260)':'#597783'}
